#ifndef DataFormatsMathfastRandomTwoSingle_H
#define DataFormatsMathfastRandomTwoSingle_H

#include <tuple>
#include <cstdint>
#include "CLHEP/Random/RandomEngine.h"
#include <cassert>

namespace fastRandom {
  namespace details {
    union DInt {
      double d;
      uint64_t l;
    };
    union FInt {
      float f;
      uint32_t i;
    };
  }  // namespace details

  // generate two single precision number in [0,1[ out of a double precision one in the same interval (as for instance generated by CLHEP...)
  // 23 bits version
  inline std::pair<float, float> twoSingle23(double d) {
    details::DInt di;
    details::FInt fi;
    di.d = d + 1.;
    //    get 2 float from one double
    fi.i = di.l & 0x007FFFFF; 
    fi.i |= 0x3F800000;  // extract mantissa as an FP number
    auto s1 = fi.f - 1.f;
    di.l = (di.l >> 23ul);  // remove those used
    //    repeat
    fi.i = di.l & 0x007FFFFF;
    fi.i |= 0x3F800000;  // extract mantissa as an FP number
    auto s2 = fi.f - 1.f;
    return {s1, s2};
  }

  // generate two single precision number in [0,1[ out of a double precision one in the same interval (as for instance generated by CLHEP...)
  // 26 bits version
  inline std::pair<float, float> twoSingle26(double d) {
    constexpr uint64_t two26 = 1UL << 26;  // 2^26
    constexpr uint64_t u26 = two26 - 1;    // 26 bits on
    constexpr float fmaxInv = 1. / double(two26);
    details::DInt di;
    di.d = d + 1.;
    //    get 2 float from one double
    uint32_t i1 = di.l & u26;
    //assert(i1<two26);
    float s1 = float(i1) * fmaxInv;
    //assert(s1>=0);
    //assert(s1<=1.f);
    uint32_t i2 = di.l >> 26;  // remuve those used;
    //    repeat
    i2 &= u26;
    //assert(i2<two26);
    float s2 = float(i2) * fmaxInv;
    //assert(s2>=0);
    //assert(s2<=1.f);
    return {s1, s2};
  }

  inline std::pair<float, float> twoSingle(double d) { return twoSingle26(d); }

  class OneFloat {
  public:
    OneFloat() = default;
    explicit OneFloat(CLHEP::HepRandomEngine& engine) : m_engine(&engine) {}

    void reset(CLHEP::HepRandomEngine& engine) {
      m_ready = false;
      m_engine = &engine;
    }

    float operator()() { return nextRN(); }

    float operator()(CLHEP::HepRandomEngine& engine) {
      // for safety we assume it is a new engine
      reset(engine);
      return (*this)();
    }

  private:
    float nextRN() {
      if (m_ready) {
        m_ready = false;
        return m_rn.second;
      }
      m_rn = twoSingle(*m_engine);
      m_ready = true;
      return m_rn.first;
    }

    CLHEP::HepRandomEngine* m_engine = nullptr;
    ;
    std::pair<float, float> m_rn;
    bool m_ready = false;
  };

}  // namespace fastRandom
#endif
